    <script type="module">
      const app = document.querySelector('#app');

      async function request(path, options) {
        const response = await fetch(path, options);
        const body = await response.json();
        if (!response.ok) throw new Error(body.error || 'Unable to complete request');
        return body;
      }

      function showError(message) {
        document.querySelector('#error').textContent = message;
      }

      function appendProject(project) {
        const row = document.createElement('div');
        row.dataset.testid = 'project-row';
        const name = document.createElement('span');
        name.textContent = project.name;
        const open = document.createElement('button');
        open.textContent = 'Open project';
        open.addEventListener('click', () => {
          location.href = `/projects/${project.id}`;
        });
        row.append(name, open);
        document.querySelector('#projects').append(row);
      }

      async function showProjects() {
        app.innerHTML = `
          <h1>Workboard</h1>
          <form>
            <label for="project-name">Project name</label>
            <div class="fields">
              <input id="project-name" name="name" type="text" autocomplete="off">
              <button type="submit" disabled>Create project</button>
            </div>
          </form>
          <div id="error" role="alert"></div>
          <div id="projects"></div>`;
        const form = app.querySelector('form');
        const input = app.querySelector('input');
        const submit = form.querySelector('button');
        form.addEventListener('submit', async (event) => {
          event.preventDefault();
          const name = input.value.trim();
          if (!name) return showError('Project name is required');
          showError('');
          submit.disabled = true;
          try {
            const project = await request('/api/projects', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ name }),
            });
            appendProject(project);
            input.value = '';
            input.focus();
          } catch (error) {
            showError(error.message);
          } finally {
            submit.disabled = false;
          }
        });
        try {
          const projects = await request('/api/projects');
          projects.forEach(appendProject);
        } catch (error) {
          showError(error.message);
        } finally {
          submit.disabled = false;
        }
      }

      async function showProject(id) {
        app.innerHTML = '<button id="back">Projects</button><h1>Loading project…</h1><div id="error" role="alert"></div>';
        app.querySelector('#back').addEventListener('click', () => { location.href = '/'; });
        try {
          const project = await request(`/api/projects/${id}`);
          app.querySelector('h1').textContent = project.name;
          document.title = `${project.name} — Workboard`;
        } catch (error) {
          app.querySelector('h1').textContent = 'Project unavailable';
          showError(error.message);
        }
      }

      const match = location.pathname.match(/^\/projects\/(\d+)$/);
      if (match) showProject(match[1]);
      else showProjects();
    </script>
